  // -----------------------------------------------------------------------
  // Apify — Apify proxy integration
  // -----------------------------------------------------------------------
  apify: {
    name: 'Apify',
    description: 'Apify proxy service with API token support',
    supportsAuth: true,

    async fetch(apiUrl, credentials) {
      try {
        const response = await axios.get(apiUrl, {
          timeout: 30000,
          responseType: 'text',
          headers: {
            'Authorization': `Bearer ${credentials?.apiToken || ''}`,
          },
        });
        return this.parse(response.data, credentials);
      } catch (err) {
        logger.error(`Apify fetch failed: ${err.message}`);
        return [];
      }
    },

    parse(content, credentials) {
      const proxies = [];
      try {
        // Apify returns JSON array of proxy objects
        const data = JSON.parse(content);
        if (Array.isArray(data)) {
          for (const item of data) {
            if (item.host && item.port) {
              proxies.push({
                host: item.host,
                port: parseInt(item.port, 10),
                username: item.username || credentials?.username || '',
                password: item.password || credentials?.password || '',
                source: 'apify',
                country: item.country || guessCountry(item.host),
                city: item.city || guessCity(item.host),
                flag: item.flag || guessFlag(item.host),
              });
            }
          }
        }
      } catch {
        // Fallback to text parsing
        const lines = content.trim().split('\n');
        for (const line of lines) {
          const parts = line.split(':');
          if (parts.length >= 2) {
            proxies.push({
              host: parts[0].trim(),
              port: parseInt(parts[1].trim(), 10),
              username: parts[2]?.trim() || credentials?.username || '',
              password: parts[3]?.trim() || credentials?.password || '',
              source: 'apify',
              country: guessCountry(parts[0]),
              city: guessCity(parts[0]),
              flag: guessFlag(parts[0]),
            });
          }
        }
      }
      logger.info(`Apify: parsed ${proxies.length} proxies`);
      return proxies;
    },
  },

