/**
 * Guess flag emoji from country code.
 */
function guessFlag(ip) {
  const country = guessCountry(ip);
  const flags = {
    GB: '🇬🇧', US: '🇺🇸', PL: '🇵🇱', FI: '🇫🇮', FR: '🇫🇷', HR: '🇭🇷',
    AL: '🇦🇱', TR: '🇹🇷', SG: '🇸🇬', DE: '🇩🇪', IN: '🇮🇳', IT: '🇮🇹',
    SE: '🇸🇪', CA: '🇨🇦', ES: '🇪🇸', SK: '🇸🇰', AT: '🇦🇹', BE: '🇧🇪',
    NL: '🇳🇱', BR: '🇧🇷', LV: '🇱🇻', ZA: '🇿🇦', TH: '🇹🇭', XX: '🌐',
  };
  return flags[country] || '🌐';
}

/**
 * Fetch proxies from any supported provider.
 */
export async function fetchProxiesFromProvider(providerName, apiUrl, credentials) {
  const provider = ProxyProviders[providerName];
  if (!provider) {
    logger.error(`Unknown proxy provider: ${providerName}`);
    return [];
  }
  return provider.fetch(apiUrl, credentials);
}

